    (21, 3, "የ፣ 18፤ ከፍ ፡ ያለ፡ የአግዚአብሔር • አራቱ ፡ መላክተ om | ኞች ፡ እኒህ ፡ ናቸው ፡ በዚያም ፡ ወራት ፡ አራ ድ ቱን ፡ ቃሎች ፡ ሰማራ ፡ አለ።"),
