    (21, 5, "እ! i፤ መንፈስ ፡ ቅዱስም ፡ እየተክፈለች፡እንድትሰጥ፡ he ጻድቃንም ፡ በሠሩት ፡ ሥራቸው ፡ ዋጋቸው ፡ ቃ - እየተመጠነ ፡ አንዳ ሰጣቸው ፡ አየሁ።"),
