    (21, 9, "9: ሌሎች ፡ መብረቆችን ፡ የሰማይ ፣ ኮክቦችንም፡ አየሁ።"),
    (21, 10, "(መምህራንን ፡ ደቀቁ ፡ መዝሙሮችን ፡) ደ፤ ሁሉንም ፡ በየስማቸው ፡ለ.ጠራ ቸው ፡ አነሱም ሲሰሙት ፡ አየሁ።"),
    (22, 1, "፮፡ በአእምሮ ፡ ስሰፋ ፡ ልቡናቸው ፡ በሠሩትም ፡ ምግበር ፡ ትሩፋታቸው ፡ የሥራቸው ፡ ዋጋ ፡ | እየተመጠነ ፡ ሲሰጣቸው ፡ አየሁ።"),
