    (22, 7, "| ፲8፣ ከቅዱሳን ፡ ማደሪያ ፡ የመላእክትንም ፡ ጌታ ፡ ስም ፡ በሚክዱ ፡ ሰዎች ፡ ላይ ፡ የተነገረ ፡ ሁለ ተኛው ፡ ነገር ፡ ይህ ፡ነው።"),
