    (55, 4, "| ፮፤ ፀሐይ ፡ የሚወጣባቸው ፡ ስድስት ፡ መስክቶ ችን ፡ አየሁ ፡ ፀሐይም ፡ የሚገበበቸው ፡ በታ ዎች ፡ ስድስት ፡ መስከቶችንም ፡ አየሁ።"),
