    (60, 2, "| ጀ፤ እንዲህ ፡ ሆኖ ፡ ይወጣል ፡ በሠላሰኛው ፡ ቀን ፡ | ማጭድነቱ ፡ ወደ ፡ ምሥራቅ ፡፣ሆና ፡ ይወጣል።"),
