        "12: ነገ ' ሠርቅ \" ሊያደርግ , ከፀሐይ ፡ ጋራ ፡ ያድ | ራል ፡ ፀሐይም ፡ በወጣ ፡ ጊዜ • ጨረቃ ፡ ከሱ ፡ ጋራ ፡ አብሮ ፡ ይወጣል ፡ ነገ ፡ በሚቀበለው ፡ ብርሃን ፡ እኩሌታ ፡ ዛሬም ፡ ይቀበላል።",
