    (76, 6, "ነ 100: ከዚሀም ፣ በኋላ ፡ በሥረኛይቱ ፡ ሱበዔ ፡ ሰበት • ፈ እጅ ፡የሚሆን፡የዘላለም,ፍርድ፡ይደረግበታል።"),
