    (76, 9, "ነe [፤ አሁንም ፡ ልጆቹ ፡ እነግራችኋለሁ ፡የግ4:፡ ሥራ. ኖ ዎችንና ፡የበጎ ፡ ሥራዎችን ' ገልሠ ፡ እስተም ኑ ራችኋለሁ።"),
    (
        76,
        10,
        "እ ፲1 ዳግመኛ ' የሚመጣበችሁን • መክራ • ታውቁ ት ዘንድ ፣ ገልፀ ፣ አስተምሪ. ችኋለሁ ፡ አሁንም ht ልጆቹ ፡ ስሙኝ ፡ በበጎ • ሥራዎች ፡ ጸንታችሁ ፡ [ey ኑሩ = [N 181 በግፍ ፡ ሥራ ፣ ጸንተው ፡ የሚኖሩ ፡ ሰዎች ፡ የ\" ሁሉ ፡ ለዘላለሙ ፡ ይጠፋሉ ፡ ል ፡ በግፍ ፡ hi | ሥራዎች ፣ ጸንታችሁ ' አትኑሩ ፡ እላችኋለሁ ረ [፱! ሕግን ' በሰው ልቡና ፡ ከምጽፍ፡ከሰው፡ሁሉ፡ ለ, ከቡር ፣ የንለሙም ፣ ሁሉ ፡ መምህር'ክምሆን፡ he -- ከኔ ፡ ከሄኖክ ፡ የተጻፈ።",
    ),
    (
        76,
        11,
        "ራ {1 ይህ፡ሁሉ፡የጥበብ፡ትምሀህርት፡ በዚህ ፡ ዓለም ከ! ለሚኖሩ ለልጆቹ ፡ ሁሉ ፡ ፍቅርንና ፡ የቀና an ነገርን ፡ ለሚሠሩ ፡ ኋላ ፡ ለሚወለት ልጆችም ፡ ተ! ትድረስ።",
    ),
    (76, 12, 'in [1 ንጹሕ፡ ክቡር ፡ገናናም፡የሚሆን‹ጌታ፡ለሰው፡ የ" ችሁ ፡ በአዝማነ ፡ መንግሥተ ፡ ሰማይን • እንዳ በt .- ታገዝን፡ትሆሁን።'),
    (76, 13, "t! ጻድቅ ሰው ከንዋመ፡ሐኬት፡ ይለያል 'ወደ፡ ይ. :. እውነት ፣ ሥራዎችም ፡ ዴሒዳል።"),
    (
        76,
        14,
        "ዶ፡ 1! ሥራውም ፡ ሁሉ ፡ አኗኗሩም ፡ በይቅርታና ፡ ከዘ በቸርነት ፡ ነው ፡ ዶገ-ንም ፡ ሰው ፡ ለዘላለሙ ፡ ለኝ ድዋር ፡ ይለዋል ፡ በሱም ፡ ለዘለዓለሙ • የቀፍ፡ [iy N ሥራ ን፣ይሰጠዋል ፡ ሥልጣንንም ይሰጠዋል።",
    ),
    (77, 1, "በሪ 111 ቸርነቱ ፡ በአውነትም ፡ ሥራ ፡ ጸንቶ ‹ይኖራል።"),
    (
        77,
        2,
        "ከብ የኢትዮጵያ ኦርቶዶክስ ተዋሕዶ ቤሣ | tጀa መጽሐፈ፡ሄኖ ቸው ፡ ዋጋ ፡ ሰበት ፡ አጥፍ ፡ ሆኖ ፡ የሚሰጣ ቸው ፡ ነቢ.ያት ፡ ፍጥረቱን ፡ ሁሉ ፡ ለማስተማር ፡ | ይመረጣሉ።",
    ),
    (77, 3, "| ቋዩ፤ ከሰው ፡ ከተወለደ ፡ ሁሉ ፡ የከበረ ፡ የጌታ ቃሉን ፡ ሰምቶ ፡የማይተዋወክ ፡ ማነው ፡ አሳቡ | ንስ ያስብ ፡ ዘንድ ፡ የሚችል ፡ ማነው።"),
    (77, 4, "| ብ! ሰማይን ፡ ሥራዋንም ፡ ሁሉ ፡ ቀና ፡ ብሎ • | ማየት ፡ የሚችል ፡ ማነው።"),
    (
        77,
        5,
        "ብ81 የሰማይን ፡ ሥራ ፡ መርምሮ ፡ ማወቅ ፡ የሚቻ ለው ፡ ከሥጋውም ፡ ለይቶ ፡ ነፍሱን ፡ ከነፍ ሱም ፡ ለይቶ ፡ ሥጋውን ፡ ማየት ፡ የሚቻለው ፡ | ይህ ነፍሴ • ነው ፡ ይህ ፡ ሥጋዬ ፡ ነው ፡ ብሎ ፡ | መናገር ፡ የሚቻለው ፡ ማነው ፡ ይህም ፡ በይ | ሆን ፡ ወደ ፡ ሰማይ ፡ መውጣት ፡ የመላእክትን | ክንፍ ፡ አይቶ ፡ የሚያስበቸው ፡ ይሀም ፡ በይ ሆን ፡ አንደነሳቸው ፡ ማድረግ ፡ የሚቻለው ፡ | ቋጀ1 የምድርን ፡ አቈልቋይዋን ፡ ወርይ.ን ፡ ምንም ፣ አንደ ፡ ሆነ ፡ ማወቅ ፡ የሚችል ፡ ሰው ፡ ሁሉ | ማነው።",
    ),
    (
        77,
        6,
        "| ሣጀ፤ የነዚህ , ሁሉ ፡ ልካቸው ፡ ለማን ፥ ተገለጠ ፡ የሰ | ማይን ፡ ምጥቀቷን ፡ ርዝመቷን ፡ ምንም ፡ አንደ ሆነ ፡ የፀናችበትም ፡ በምንም ፡ ላይ ፡ እንደ ፡ሆነ፡ መርምሮ ፡ ማወቅ ፡ የሚችል ፡ የክኮክበችም ፡ ቀ.ጥራቸው ፣ ምን ፡ ያህል ፡ እንደ ፡ሆነ፡ ፀሐይ ፣ | ጨረቃም ሁሉ ፡ በየትም ፡አንዲያርፉ፡ማወቅ፡ | የሚቻለው ፣ ሰው ፡ ሁሉ ፡ ቢኖር ፡ በሱ ፡ ነው።",
    ),
    (77, 7, "81 እሁንም ፡ ልጆቹ ፡ እውነተኛይቱን ፡ ሕግ | ውደዷት የውነት ፡ ሥራዎችን ይቀበሏቸው፡ | ዘንድ • ይገበልና • በሷም ፡ ጸንታችሁ ፡ ኑሩ፡ | እላችኋለሁ።"),
    (77, 8, "| ዩ፤ የግፍ ፡ ሥራዎች ፡ ግን ፣ ፈጥነው ፡ ይጠፋሉ ፡ ያንሳሉ ፡ በደግነት ፡ ለታወቁ ፡ ሰዎችም ፡ ከልጅ።"),
    (77, 9, "| ልጅ ፡ ጀምሮ የሞትና የግፍ ፡ ሥራዎች ፡ ይገ | ለጣሉ ፡ ሰዎችም ፡ ከነሳቸው ፡ ይርቃሉ • እነ | ሱንም ፣ አይከተሏቸውም።"),
    (
        78,
        1,
        "[1 አሁንም ፡ ለናንተ ፡ ለወዳጆቹ ፡ በግፍና ፡ በክፉ ሥራዎች ሞትን ፡ በሚያመጡ ፡ ሠራዎች | ጸንታ ችሁ • አትኑሩ ፡ አውነት ፡ ነገርን ፡ የተመ | ረጠች ፡ድኅነታችሁንም ፡ለናንተ፡ ፈጽማችሁ | ውደዱ ፡ አንዲ ፡ አንዳትጠፉ ፡ ወደነሱ ፡ አትቅ ረቡ ፡ አላትኋዳለሁ።",
    ),
    (78, 2, "| ፱፤1 በፍቅር ፡ ሥራዎትም ፡ ጸንታችሁ ፡ ኑሩ ፡ ትድ | ናላችሁ፡ በተድላ፡ ደስታውም, ትዘጋጃላችሁ፡ | በልቡናችሁም ' አሳብ ፡ ሕጉን ፡ ትይዛላችሁ።"),
    (
        78,
        3,
        "| ፻1 ክፉ ፡ ጥበብን • ይሠሩ ፡ ዘንድ ፡ ደጋጎች ፡ ሰዎ ችን ፡ ክፉዎች ፡ ሰዎች ፡ አንዳ ፈትኗቸው ፡ አው ቃለሁና ፡ ነገሬ ፡ ከልቡናችሁ ፡ አይጥፋ ፡ ለኃ ጢእአትም ፣ ልቡና ፡ ሁሉ ፡ አይገኝላት ፡ ሕግ | በ.ያፈርሱ ፡ የሚመጣው ፡ መከራ ፡ ሁሉ ፡ አያን ፮! እነሱ ፡ ፈጥነው ፡ ይጠፋሉና ፡ ፍቅር ፡ አንድነ a ._ _ . Wo የኢትዮጵያ ኦርቶዶክስ ተዋባሕነዶ ቤቢ 1031 መጽሐፈ፡ቶኖክ እንዳጠፉ ፣ እንደ ፣ ወደዳችሁ • ሥልጣንም • በነሳቸው ፡ አንዲደረግ ፡ ወዳጆቹ ፡ ጻድቃን • ይሀንን ፣ ተስፋ ፣ አደረጉ።",
    ),
    (78, 4, "ጽ! ኃጥአን • መከሪ. • በሚቀበሉበትም ፡ ቀን • የና ንተ ፡ ልጆች ፡እንዳሞሮች ፡ ተነሥተው ከፍ ከፍ ፡ ይላሉ።"),
    (
        78,
        5,
        "ጽክ፣ ቦታትሆሁም ፡ ከጥንብ ፣ አሞራ • ቦታ ፡ ይልቅ | ይርቃል • ወጥታችሁም ፡ ወደ ፣ ቀበሮ • ጐድ ጎድ ፡ ክዘመፀኞ ችም ፡ ፊት ፡ የተነሣ ፡ እንደ ፡ Pas ፡ ለዘላለሙም ፡ ወደ ፡ ገደል • ጥግ ፡ ትገበ | ለተ።",
    ),
    (
        78,
        6,
        "ሾዩ፣ በናንተም ፡ላይ፡ ክፉ ፡ ሥራቸውን ፡ ይሠራሉ ፡ ይህ ፡ ኃጢአታችሁ ፡ በናንተ ፡ ምስክር ፡ ይሆን | በችኋል « እንጂ ፣ እናንተ ፡ እንደነሱ ፡ አትሆ | ነም ፡ ለወንድሞቻችሁም ፡ ከኃጥአንም፣ ጋራ፡ | አንድ ፡ ሆናችሁ ፡ አንደ ሄለይም ፡ ቃላቸውን ፡ አቅቀጥነው ፡ ያለቅሳሉ።",
    ),
    (
        78,
        7,
        "ሸ፫!1 ይህ • መከራው ፡ ለናንተ • ድሣነት ፡ ይሆንላች ኋልና ፡ የበራ.ም ፡ ብርሃን ፡ ለናንተ ፡ ያበራላች ኋልና ፡ ከሰማይም ፡ ዕረፍት ፡ የሚደረግበትን | ቃል ፡ ትሰማላችሁና ፡ መከራ ፡ የምትቀበሉ ፡ | ጻድቃን ፡ እናንተ ፡ ግን • አትፍሩ።",
    ),
    (
        78,
        8,
        "| ሸ8፤! በለጸግነታ ችሁ ፡ ደጋግ ፡ ሰዎችን ፡ ያስመስላች ዳልና ፡ እናንተ ፡ ክፉዎች ፡ኃጥአን ፡ ወዮላችሁ፡ ልቡናችሁ ፡፣ ግን • አናንተ • በደለኞች ፡ አንደ ሆናችሁ ፣ ይዘልፋ.ች:ኣል።",
    ),
    (
        78,
        9,
        "(ያየውቅበችኋል | ሸዩ! ይህም ፡ ነገር • በናንተ ፡ ለክፋ ታችሁ ፡ መታስ ቢያ ፡ ምስክር ፡ ዴሆናል ፡ አለ = | ሸቖ፤ ዞፈራውን፣፡ስንይዴ፡፣ የምትበሉ ፡ክላምም፡ ጡት የተገኘ ፡ ወተቱንም • የምትጠጡ ፥ የተዋረዱ ችን ፡ ሰዎት ፡ በኃይላችሆሁ ፡ የምትረጋግጫጠ. ቱው ፣ ለናንተ ፣ ወዙላችሁ = | ጽዃ፣ የኃጠክአታችሆሁን ፡ ፍዳ ፡ ፈጥናችሁ ፡ ትቀበላላ ችሁና ፡፣ሆሁል፡ ጊዜ ፣ ውኃን ፣ ለምትጠጡ፡ሰዎች፡ ወዮላችሁ ፡ የሕይወት ፡ መገኛ ፡ ሕጉን ፡ ትታ - ችኋልና • ፈጽማችሁ ፡• ትጠፋላችሁ = ሸሯ! በደልን ፡ ተንኩኰልን • ስድብን ፡ ለምትሠሩ ለናንተ ፡ ወዮላችሁ ፡ ይህም ፡ በናንተ ፡• የክፋታ ችሁ, መታሰቢያ ፡ ይሆናል = ቤዘ! የምትጠብት ፣ ቀኝ ፡ ትመጣለችና • ፉገን ሰው ፣ በኃይላችሁ ፡ ራስ ፡ ራሱን ፡ ለምትቀጠ - ቅጡት ፡ ለናንተ ፡ ለኃይለኞች ፡ ወዮላችሁ።",
    ),
    (78, 10, "ብሽ! በነዚያ ፡ ወራቶች ፥ ለደጋግ ፡ ሰዎች ፡ በናንተ በተፈረደጾበችሆ ፡ ቀን • ደጋጎችና ፡ ብዙዎች መራቶች ፡ ይመጣሉ ፡ አለ።"),
    (78, 11, "ስ! ሓጥክን ፡ ለስድብ • እንዲሆኑ ፡ ግፍም ፡• በሠ ሩበት ፡ ቀን ፡ እንዲጠፉ ፡ ወዳጆቹ ፡ ጻFቃን ፡ አመኑ።"),
    (78, 12, "ዩ1 እግዚአብሔር ፡ የናጎተን ፡ ጥፋት ፡ ያስባልና • በሰማይም ፡ ያሉ፡ መላእክት ፡ በናንተ ፡ ጥፋት ፡ ላለይ ፡ ዶስ ፡ ይላቸዋልና ፡ ይህ • በዶግነታችሁ፡።"),
    (78, 13, "የታወቁ ፣ ይሆንላችኋል።"),
    (78, 14, "የኢትዮጵያ ኦርቶዶክስ ተዋሕዶ ቤ IFaE መጽሐፈ፡ሄናኖ ክልተላከችም ፡ አቧንም ፡ የሠሯት ፡ ሰዎች ፡ ለጽኑ ፣፡ መርገም ፡ ይሆናሉ ፡ ( ሑሩ ፡ ይበላሉ )።"),
    (78, 15, "19: በጅዋ ፡ በሠራ ችው ፡ ሥራ ፡ ልጅ ፡ ሳትወልድ ትሞታለች ፡ እንጂ ፡ ለሴትም ፡ መምክን ፡ አል ተሰጣትም ፡ ነበር።"),
    (
        78,
        16,
        "| ጽ፤ ኃጥአን ፣፡ክፉ፡ ሠራችሁ ፡ሁሉ፡ በሰማይ ፡ እንደ፡ | ተገለጠ ፡ ፈጽሞም ፡ የተሠወረ ፡የግፍ፡ ሥራም | እንደሌላ ትሁ ፡ በገናናና ፡ በከበረ ፡ ስሙ ፡ ምዬ፡ ነገርኋችሁ።",
    ),
    (
        78,
        17,
        "ጽፅ፤ በሰውነታ ትሁ ፡ በልቡና ችሁም ፡ የሚሠወርላ ችሁ ፡ አታስመስሉት ፡ በሰማይ ፡ በአግዚአብ ሔር ፡ፊት ይጻፍ ፡ዘንድ ፡ አንዳለው ፡ በየቁኑ፡ የሠራችሁትን ፡ ሁሉ ፡ ፈጽማችሁ ፡ አታውቁ | ምና ፡ በልቡናችሁ ፡ ይሠወርልናል አትበሉ።",
    ),
    (
        79,
        1,
        "| ቤዩ፤ ፍርድ ፡ አስከሚፈረድበት፡ እስክ ዕለተ ፡ ምጽ | አት ፡ ድረስ ፡ የበደላችሁት ፡ በደል ፡ በየቀኑ ፡ | ሁሉ ፡ አንዲጻፍበ ችሁ ፡ ከዛሬ ፡ ጀምሮ ፡ ታው ቃላችሁ ጸ[፤ በስንፍና ትሁ ፡ ትጠፋፉላችሁና ፡ መምራንንም እትሰሟቸውምና ፡ በጎ ፡ ነገርም ፡ አታገኛችሁ ምና ፡ አናንት ፡ ሰነፎች ፡ ወዮላችሁ።",
    ),
    (
        79,
        2,
        "| ጽ፱፤1 አሁንም ፡ ጥፋት ፡ ለታዘዘበት ፡ ቀን ፡ አናንተ | የተዘጋጃ ትሁ ፡ እንደሆናችሁ ፡ አወቁ ፡ ተፈር | ዶበችሁ፡ ወደገሃነም ትሄዳላችሁ ፡አንጃ ፡ ኃጥ እን ፡አንድናለን ፡ ብላችሁ ፡ ተስፋ ፡ አታድርጉ።",
    ),
    (
        79,
        3,
        "ጽ፻፤ ጽኑ ፡ ፍርድ ፡ ለሚፈረድበት ፡ ቀን, መከራም በታዘዘበት ፡ በሰውነታ ችሁም ፡ ታላቅ ፡ ኮስ ልና ፡ በታዘዘበት ፡ ቀን ፡ ለጥፋት ፡ ተዘጋጅታ ችኋልና ፡ ምግባርን ፡ ስላላወቃችሁ ፡ በነፍስ፡ ትሞታላች።",
    ),
    (
        79,
        4,
        "| 821 ክፉ ፡ ሥራን ፡ የምትሠሩ ፡ ብርንዶንም የም | ትበሉት ፣ አናንት ፡ ልበ ፡ ድንጋዎች ፡ ወዮላ ችሁ ፡ ገናና ፡ አግዚአብሔር ፡ በዚህ ፡ ዓላም አብዝቶ ፡ የፈጠረው ፡ ፍጥረት ሁሉ ፡ የመሪ ነው ፡ እያላትሁ ፡ በተድላ ፡ በደስታ ፡ ትበላላ | | ችሁ ፡ ትጠጣላችሁ ፡ ትጠግባላችሁ ፡ አናንተ | ከወዴት ፡ አግኝታ ችሁት ፡ ነው ፡ አንድነትም ፡ የላችሁም።",
    ),
    (79, 5, "ቑ፮፤ የበደልን ፡ ሥራ ፡ ለምትወደዴት፡ ለናንተ ፡ ወዮ ላችሁ ፡ በጎይቱንስ ፡ ለምን ፡ ትመኛታላችሁ።"),
    (
        79,
        6,
        "፤ በጻድቃንም ፡ አጆች ፡ አልፋችሁ ፡ ትያዙ ፡ ዘንድ ፡ አደላትሁ ፡ አወቁ ፣ አንገቶቻችሁንም፡ ቆርጠው ፡ ይገሏችኋል ፡ ከዚያም ፡ አስቀድ | መው ፡ አይራሩላችሁም።",
    ),
    (80, 1, "| ጽ፱1 ለናንተ ፡ መቃብር ፡ አይቆፍሩላችሁምና ፡ በጻ ድቃን ፡ መክራ ፡ ደስ ፡ ለሚላችሁ ፡ ለናንተ ወዮላችሁ።"),
    (80, 2, "1 የድዓነት ፡ አለኝታ ፡ አይደረግላችሁምና፡ የመ ን ፣ ነገር ፡ ለምትንቁ ፡ ለናንት ፡ ወዮላ ሁ።"),
    (
        80,
        3,
        "ብክ ሐሀት ፡ ነገራቸውን ፡ ይሰሟት፡ ዘንድ፡ ስንፍና ቸውንም ፡ አንዳይዘነጓት ፡ አነሱ ፡ አሰታቸውን፡ ድይጽፋሉና ፡ ሕኑን ፡ የዘነጉ ፡ ሰዎች ፡ ነገርንና የአሰትን ፡ ነገር ፡ ለምትጽፉ ፡ ለናንት ፡ ወዮላ የኢትዮጵያ ኦርቶዶክስ ተዋሕዶ ቤኘ 1033 መጽሐፈ፡ቱናኖ 13: የልሁል ፡ የእግዚአብሔርንም ፣ ሥራዎች፡ይሠ በ ራቸዋል ፡ በውነተኛም ፡ ሥራዎች ፣ ጸንተው F ይኖራሉ ፣ እነሱ ፡ ይድናሉና ፡ ሕጉን ፡ አንደ በ ዘነጉ ፡ ሰዎች ፣ ሕጉን ፡ አይዘነጉም።",
    ),
    (80, 4, "ነ {፱፣ በሲኦል • ትጠፋላችሁና • ለወንድማችሁ ፡ ክፉ [l ውን ፣ ነገር • አብዝታችሁ ፡ የምትሠሩ ፡ ለእና L | ንተ ፡ ወዮላችሁ።"),
    (
        80,
        5,
        "0 | ፲፪፣ በሱ ፣፡ትጠፋላችሁና ፣ ተንኮልንና ፣ ኃጢአትን እ መሠረት ፣ ንፍገትን ፡ የምትሠሩ ፡ በዚህም ፡ ጾ ዓለም ፡ አግዚአብሔርን ፡የምትአሳገዝኑ ፡ ሰዎች ፡ 7 ወዮላችሁ።",
    ),
    (
        80,
        6,
        "ላ {81 በድሓኃ፡ገንዘብ፡ቤ ታችሁን፡የምትሠሩ፡አናንተ፣ L | ወዮላችሁ ፣ ሥሪ-ዥውም ፣ ሁሉ ፡ ውብ ፡ ነው 3 የኃጠ.አትም ፣ የሚሠረ.በት ፣. ደንጋይ ፣ ነው t Ly አንድነትም • እንደሌላችሁ ' አኔ ፡ እነግራት ኋ i ለሆ።",
    ),
    (
        80,
        7,
        "[ ፲፮1 ለዘለዓለሙ ፡ የሚኖር, የአበቶቻዥቾው፡ ርስትና ፣ l ድንበርን ፡ ለሚያፈርሱ • ሰዎች ፡ ወዮላቸው ፡ በ ለነሱ ፡ ዕረፍተ ፡ ነፍስ ፡ አይደረግምና ፡ ልበ'ና [l ዛው ንም ፡ ወይ ፡ ጣፆቱ ፡ ይወስዱታል ነ | {1፳!1 በደልን ፡ የምትሠራት ፣ ግፍንም ፡ ለምትሩ ለ ደ.ት፡ለናንተ፡ ወዮላችሁ ፡ጌትነታችሁን፡ የጠ ሪ ፋዋልና ፡ በልቡና ችሁም ፣ ክፋትን ' ያላድርበ ቫ ችኋልና ፡ ጽኑ፡ቁ፡ርድ እስከሚፈረድባበት፡እአስከ፡ በ ዕለተ ፡ ሦጽአት ፡ ድረስ ፡ በልንጀሮቻችሁን • L ለምትገሉ ፡ ሰዎች ፣ ወዮላችሁ።",
    ),
